CREATE POLICY "Membros podem inserir documentos fiscais" ON public.fiscal_documents FOR INSERT TO authenticated WITH CHECK (EXISTS (SELECT 1 FROM organization_members om JOIN companies c ON c.organization_id = om.organization_id WHERE c.id = fiscal_documents.company_id AND om.user_id = auth.uid()));
CREATE POLICY "Membros podem atualizar documentos fiscais" ON public.fiscal_documents FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM organization_members om JOIN companies c ON c.organization_id = om.organization_id WHERE c.id = fiscal_documents.company_id AND om.user_id = auth.uid())) WITH CHECK (EXISTS (SELECT 1 FROM organization_members om JOIN companies c ON c.organization_id = om.organization_id WHERE c.id = fiscal_documents.company_id AND om.user_id = auth.uid()));
CREATE POLICY "Membros podem excluir documentos fiscais" ON public.fiscal_documents FOR DELETE TO authenticated USING (EXISTS (SELECT 1 FROM organization_members om JOIN companies c ON c.organization_id = om.organization_id WHERE c.id = fiscal_documents.company_id AND om.user_id = auth.uid()));